//! NPC placement report (headless, no window): counts per area and a ground check of every placement variant.
//!
//! Reads `data/npc_placements.tsv` (generated by `.tools/npc_decode.py`). For each data area:
//! * npc records (distinct keys), npc variants, npc_pokemon variants, generic (cc) / unique (tr) characters;
//! * ground check like `placement_terrain_check` / `spawn_terrain_check`: main areas `ha_area00..05` against the
//!   terrain heightmap (`TerrainArea::sample_world_height`), every area (sub-areas included, each in its own frame)
//!   against its own Havok navmesh (`archive/field/terrain/<area>.gfpak`, first mesh). "ok" = |dy| <= 3 m.
//!
//! Usage: `cargo run --release -p pla --example npc_report [-- <romfs_patched/bin> [tsv]]`
//! Without the game data it prints `[skip]` and exits 0.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::path::PathBuf;

use pla::assets::navmesh::{load_pack_navmeshes, NavMesh};
use pla::assets::terrain::TerrainArea;

#[derive(Default)]
struct Area {
    keys: BTreeSet<String>,
    npc: usize,
    poke: usize,
    cc: usize,
    tr: usize,
    timed: usize,
    gated: usize,
    origin: usize,
    pts: Vec<[f32; 3]>,
    poke_pts: Vec<[f32; 3]>,
}

#[derive(Default)]
struct Check {
    n: usize,
    ok: usize,
    sum: f64,
    /// Points with no navmesh polygon within 1 m horizontally (not counted in `n`).
    off: usize,
}

impl Check {
    fn add(&mut self, d: Option<f32>) {
        if d.is_none() {
            self.off += 1;
        }
        if let Some(d) = d {
            self.n += 1;
            self.sum += f64::from(d);
            if d <= 3.0 {
                self.ok += 1;
            }
        }
    }
    fn show(&self) -> String {
        if self.n + self.off == 0 {
            return "-".into();
        }
        let all = self.n + self.off;
        format!("{}/{} ({:.1}%, mean |dy| {:.2} m, no ground {})", self.ok, all, 100.0 * self.ok as f64 / all as f64, self.sum / self.n.max(1) as f64, self.off)
    }
}

/// Smallest |dy| over every navmesh of the pack (multi-storey interiors have several), `None` = no polygon within 1 m.
fn nav_dy(meshes: &[NavMesh], p: [f32; 3]) -> Option<f32> {
    meshes
        .iter()
        .filter_map(|m| match m.height_at(p[0], p[2]) {
            Some(y) => Some((y - p[1]).abs()),
            None => m.nearest(p[0], p[2], 1.0).map(|h| h.distance.max((h.y - p[1]).abs())),
        })
        .min_by(f32::total_cmp)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let root = PathBuf::from(args.get(1).cloned().unwrap_or_else(|| "/home/nico/work/decompilacion/work/pla/pk2/romfs_patched/bin".into()));
    let tsv = args.get(2).map_or("data/npc_placements.tsv", String::as_str);
    if !root.join("archive/field/terrain").is_dir() {
        println!("[skip] game data not found under {}", root.display());
        return;
    }
    let text = std::fs::read_to_string(tsv).unwrap_or_else(|e| panic!("{tsv}: {e}"));
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    let header: Vec<&str> = lines.next().unwrap_or_default().split('\t').map(|h| h.split(':').next().unwrap_or("")).collect();
    let col = |name: &str| header.iter().position(|h| *h == name).unwrap_or_else(|| panic!("column {name}"));
    let (ca, ck, ckey, cch, cx, cy, cz, crole) =
        (col("area"), col("kind"), col("key"), col("chara_kind"), col("x"), col("y"), col("z"), col("cond_role"));
    let mut areas: BTreeMap<String, Area> = BTreeMap::new();
    for l in lines {
        let c: Vec<&str> = l.split('\t').collect();
        let a = areas.entry(c[ca].to_owned()).or_default();
        if c[ck] == "npc" {
            a.npc += 1;
            a.keys.insert(c[ckey].to_owned());
            match c[cch] {
                "cc" => a.cc += 1,
                "tr" | "special" => a.tr += 1,
                _ => {}
            }
        } else {
            a.poke += 1;
        }
        let role = c[crole];
        if role.starts_with("time_zone") {
            a.timed += 1;
        } else if role != "none" && role != "default" {
            a.gated += 1;
        }
        let p = [c[cx], c[cy], c[cz]].map(|v| v.parse::<f32>().unwrap_or(0.0));
        // Variants at exactly (0,0,0) carry no position (LIKELY: the NPC is absent in that state); not ground-checked.
        if p == [0.0; 3] {
            a.origin += 1;
        } else if c[ck] == "npc" {
            a.pts.push(p);
        } else {
            a.poke_pts.push(p);
        }
    }
    let mut terrains: HashMap<String, TerrainArea> = HashMap::new();
    for t in 0..=5u8 {
        match TerrainArea::load(&root, t) {
            Ok(a) => {
                terrains.insert(format!("ha_area{t:02}"), a);
            }
            Err(e) => eprintln!("terrain {t}: {e}"),
        }
    }
    println!("area\tnpc_records\tnpc_variants\tcc\ttr\tnpc_pokemon\ttime_gated\tstory_gated\tat_origin\theightmap_within3m\tnavmesh_within3m");
    let mut tot_h = Check::default();
    let mut poke_n = Check::default();
    let (mut sub_n, mut main_n) = (Check::default(), Check::default());
    let mut totals = [0usize; 6];
    for (name, a) in &areas {
        let mut h = Check::default();
        if let Some(t) = terrains.get(name.as_str()) {
            for p in &a.pts {
                h.add(t.sample_world_height(p[0], p[2]).map(|y| (y - p[1]).abs()));
            }
        }
        let mut n = Check::default();
        let nav = load_pack_navmeshes(&root.join("archive/field/terrain").join(format!("{name}.gfpak")))
            .ok()
            .filter(|v| !v.is_empty());
        match &nav {
            Some(m) => {
                for p in &a.pts {
                    n.add(nav_dy(m, *p));
                }
                for p in &a.poke_pts {
                    poke_n.add(nav_dy(m, *p));
                }
            }
            None => eprintln!("{name}: [skip] no navmesh pack"),
        }
        println!(
            "{name}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}",
            a.keys.len(),
            a.npc,
            a.cc,
            a.tr,
            a.poke,
            a.timed,
            a.gated,
            a.origin,
            h.show(),
            if nav.is_some() { n.show() } else { "[skip]".into() }
        );
        for (t, v) in totals.iter_mut().zip([a.keys.len(), a.npc, a.cc, a.tr, a.poke, a.origin]) {
            *t += v;
        }
        let bucket = if name.len() > 9 { &mut sub_n } else { &mut main_n };
        bucket.n += n.n;
        bucket.ok += n.ok;
        bucket.sum += n.sum;
        bucket.off += n.off;
        tot_h.n += h.n;
        tot_h.ok += h.ok;
        tot_h.sum += h.sum;
        tot_h.off += h.off;
    }
    println!(
        "summary: {} areas; npc records {}, npc variants {} (cc {}, tr/special {}), npc_pokemon variants {}, at origin {}; \
         npc ground checks (|dy| <= 3 m): heightmap (main areas) {}; navmesh main areas {}; navmesh sub-areas {}; \
         npc_pokemon on navmesh {}",
        areas.len(),
        totals[0],
        totals[1],
        totals[2],
        totals[3],
        totals[4],
        totals[5],
        tot_h.show(),
        main_n.show(),
        sub_n.show(),
        poke_n.show()
    );
}
